-- Primeiro lote: 22 questões de julgamento extraídas da coletânea do Drive.
-- Grava em curated_question_catalog como under_review; não publica.
-- Preserva origem, gabarito e autoria não original.
begin;
do $guard$ begin
 if (select count(*) from public.syllabus_topics t join public.syllabus_editions e on e.id=t.edition_id where e.contest_name='Polícia Federal' and e.role_name='Agente de Polícia Federal' and e.contest_year=2025 and e.status='active' and t.discipline='Noções de Direito Constitucional' and t.topic_order=1 and t.content_status='current' and t.block_name not ilike '%Hist%') <> 1 then raise exception 'Edital ativo e tópico PF 2025 não encontrados de forma única; lote não aplicado.'; end if;
end $guard$;
with incoming as (select * from jsonb_to_recordset('[{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-9","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":9,"source_origin":"CEBRASPE (CESPE) - AJ STJ/STJ/Administrativa/2018","contest_year":2018,"question_text":"A respeito dos direitos e garantias fundamentais, julgue o item que se segue, tendo como referência a jurisprudência do Supremo Tribunal Federal. O rol dos direitos fundamentais previsto na Constituição Federal de 1988 é taxativo, isto é, o Brasil adota um sistema fechado de direitos fundamentais.","official_answer":"E","explanation":"O catálogo constitucional admite outros direitos. Origem declarada pela coletânea: CEBRASPE (CESPE) - AJ STJ/STJ/Administrativa/2018. Item 9 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"5º, § 2º","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false},{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-11","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":11,"source_origin":"CEBRASPE (CESPE) - PRF/PRF/2019","contest_year":2019,"question_text":"À luz da Constituição Federal de 1988, julgue o item que se segue, a respeito de direitos e garantias fundamentais e da defesa do Estado e das instituições democráticas. Em caso de iminente perigo público, autoridade pública competente poderá usar a propriedade particular, desde que assegure a consequente indenização, independentemente da comprovação da existência de dano, que, nesse caso, é presumido.","official_answer":"E","explanation":"A indenização exige dano. Origem declarada pela coletânea: CEBRASPE (CESPE) - PRF/PRF/2019. Item 11 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"5º, XXV","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false},{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-12","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":12,"source_origin":"CEBRASPE (CESPE) - PRF/PRF/2019","contest_year":2019,"question_text":"À luz da Constituição Federal de 1988, julgue o item que se segue, a respeito de direitos e garantias fundamentais e da defesa do Estado e das instituições democráticas. São constitucionalmente assegurados ao preso o direito à identificação dos agentes estatais responsáveis pela sua prisão e o direito de permanecer em silêncio.","official_answer":"C","explanation":"Silêncio e identificação são garantias do preso. Origem declarada pela coletânea: CEBRASPE (CESPE) - PRF/PRF/2019. Item 12 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"5º, LXIII e LXIV","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false},{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-14","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":14,"source_origin":"CEBRASPE (CESPE) - PRF/PRF/2019","contest_year":2019,"question_text":"A respeito do tratamento constitucional dos tratados internacionais de direitos humanos, julgue o item que se segue. A hierarquia constitucional dos tratados internacionais de direitos humanos depende de sua aprovação por três quintos dos membros de cada casa do Congresso Nacional.","official_answer":"C","explanation":"O quórum qualificado integra o rito constitucional. Origem declarada pela coletânea: CEBRASPE (CESPE) - PRF/PRF/2019. Item 14 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"5º, § 3º","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false},{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-15","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":15,"source_origin":"CEBRASPE (CESPE) - AAP (PGE PE)/PGE PE/Calculista/2019","contest_year":2019,"question_text":"À luz da Constituição Federal de 1988, julgue o item a seguir. O direito de propriedade é constitucionalmente garantido, devendo as propriedades atender a sua função social.","official_answer":"C","explanation":"A propriedade deve cumprir função social. Origem declarada pela coletânea: CEBRASPE (CESPE) - AAP (PGE PE)/PGE PE/Calculista/2019. Item 15 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"5º, XXII e XXIII","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false},{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-51","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":51,"source_origin":"CEBRASPE (CESPE) - Tec MPU/MPU/Apoio Técnico e Administrativo/Administração/2018","contest_year":2018,"question_text":"Com base nas disposições constitucionais acerca de princípios, direitos e garantias fundamentais, julgue o item a seguir. Policiais têm a prerrogativa de adentrar na casa de qualquer pessoa durante o período noturno, desde que portem determinação judicial ou o morador consinta.","official_answer":"E","explanation":"Mandado judicial não basta para entrada noturna. Origem declarada pela coletânea: CEBRASPE (CESPE) - Tec MPU/MPU/Apoio Técnico e Administrativo/Administração/2018. Item 51 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"5º, XI","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false},{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-53","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":53,"source_origin":"CEBRASPE (CESPE) - Tec (FUB)/FUB/Tecnologia da Informação/2018","contest_year":2018,"question_text":"Com base nas disposições constitucionais acerca de princípios, direitos e garantias fundamentais, julgue o item a seguir. Os tratados internacionais sobre direitos humanos possuem status de emendas constitucionais, de maneira que a autoridade pública que a eles desobedecer estará sujeita a responsabilização.","official_answer":"E","explanation":"A equivalência não é automática. Origem declarada pela coletânea: CEBRASPE (CESPE) - Tec (FUB)/FUB/Tecnologia da Informação/2018. Item 53 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"5º, § 3º","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false},{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-54","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":54,"source_origin":"CEBRASPE (CESPE) - Tec MPU/MPU/Apoio Técnico e Administrativo/Administração/2018","contest_year":2018,"question_text":"Acerca de classificação constitucional, de princípios, direitos e garantias fundamentais e de servidores públicos, julgue o seguinte item. A ampla defesa e o contraditório são princípios constitucionais fundamentais decorrentes do devido processo legal aplicáveis tanto ao cidadão em geral quanto aos servidores públicos.","official_answer":"C","explanation":"As garantias abrangem processos administrativos. Origem declarada pela coletânea: CEBRASPE (CESPE) - Tec MPU/MPU/Apoio Técnico e Administrativo/Administração/2018. Item 54 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"5º, LIV e LV","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false},{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-59","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":59,"source_origin":"CEBRASPE (CESPE) - ACE (TCE-PE)/TCE\u0002PE/Auditoria de Contas Públicas/2017","contest_year":2017,"question_text":"Acerca da organização político-administrativa do Estado, dos princípios constitucionais e dos direitos e garantias fundamentais, julgue o item a seguir, com base nas disposições da CF. De acordo com a CF, somente estarão isentas do pagamento de taxa para obtenção de certidões em repartição pública para defesa de direitos as pessoas que comprovarem sua hipossuficiência.","official_answer":"E","explanation":"A gratuidade independe de pobreza. Origem declarada pela coletânea: CEBRASPE (CESPE) - ACE (TCE-PE)/TCE\u0002PE/Auditoria de Contas Públicas/2017. Item 59 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"5º, XXXIV, b","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false},{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-60","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":60,"source_origin":"CEBRASPE (CESPE) - ACE (TCE-PE)/TCE\u0002PE/Auditoria de Contas Públicas/2017","contest_year":2017,"question_text":"Acerca da organização político-administrativa do Estado, dos princípios constitucionais e dos direitos e garantias fundamentais, julgue o item a seguir, com base nas disposições da CF. Ainda que se configure relativização do princípio da inviolabilidade da vida privada, admite-se a divulgação na mídia de informações a respeito de indivíduo que exerça cargo público, bastando que se ateste previamente a veracidade delas.","official_answer":"E","explanation":"A veracidade não elimina a proteção da intimidade. Origem declarada pela coletânea: CEBRASPE (CESPE) - ACE (TCE-PE)/TCE\u0002PE/Auditoria de Contas Públicas/2017. Item 60 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"5º, X","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false},{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-73","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":73,"source_origin":"CEBRASPE (CESPE) - TJ TRF1/TRF 1/Administrativa/Segurança e Transporte/2017","contest_year":2017,"question_text":"Considerando o que dispõe a Constituição Federal de 1988 (CF) sobre direitos humanos, julgue o item que se segue. Desde que não frustrem outra reunião anteriormente convocada para o mesmo local, todos podem reunirse em locais abertos ao público, independentemente de autorização, sendo apenas exigido prévio aviso à autoridade competente.","official_answer":"C","explanation":"A reunião exige aviso, não autorização. Origem declarada pela coletânea: CEBRASPE (CESPE) - TJ TRF1/TRF 1/Administrativa/Segurança e Transporte/2017. Item 73 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"5º, XVI","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false},{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-74","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":74,"source_origin":"CEBRASPE (CESPE) - AJ STJ/STJ/Administrativa/2018","contest_year":2018,"question_text":"A respeito dos direitos e garantias fundamentais, julgue o item que se segue, tendo como referência a jurisprudência do Supremo Tribunal Federal. É vedado ao legislador editar lei em que se exija o pagamento de custas processuais para a impetração de habeas corpus.","official_answer":"C","explanation":"Habeas corpus é gratuito. Origem declarada pela coletânea: CEBRASPE (CESPE) - AJ STJ/STJ/Administrativa/2018. Item 74 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"5º, LXXVII","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false},{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-89","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":89,"source_origin":"CEBRASPE (CESPE) - Aux Inst (IPHAN)/IPHAN/Área 1/2018","contest_year":2018,"question_text":"A respeito dos direitos e das garantias fundamentais, julgue o item seguinte. O mandado de segurança é o remédio constitucional adequado para garantir o acesso à informação constante de banco de dados de entidades governamentais, uma vez que o direito a informação é direito líquido e certo.","official_answer":"E","explanation":"Dados pessoais ensejam habeas data. Origem declarada pela coletânea: CEBRASPE (CESPE) - Aux Inst (IPHAN)/IPHAN/Área 1/2018. Item 89 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"5º, LXXII, a","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false},{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-90","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":90,"source_origin":"CEBRASPE (CESPE) - AUCE (TCE-PE)/TCE\u0002PE/Auditoria de Obras públicas/2017","contest_year":2017,"question_text":"A respeito do controle jurisdicional da administração pública no direito brasileiro, julgue o item a seguir. O remédio constitucional do habeas data permite que o impetrante obtenha informações cadastrais relativas a todas as partes de um processo do qual seja parte, exceto aquelas protegidas por sigilo bancário.","official_answer":"E","explanation":"O acesso se refere ao próprio impetrante. Origem declarada pela coletânea: CEBRASPE (CESPE) - AUCE (TCE-PE)/TCE\u0002PE/Auditoria de Obras públicas/2017. Item 90 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"5º, LXXII, a","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false},{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-91","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":91,"source_origin":"CEBRASPE (CESPE) - Def PF/DPU/2017","contest_year":2017,"question_text":"A respeito da teoria e do regime jurídico dos direitos fundamentais, julgue o item que se segue à luz das disposições da CF. Sob o aspecto da legitimidade ativa, por meio de habeas data é possível obter informações relativas a qualquer pessoa, desde que as informações sejam classificadas como públicas.","official_answer":"E","explanation":"Habeas data não permite investigar terceiros. Origem declarada pela coletânea: CEBRASPE (CESPE) - Def PF/DPU/2017. Item 91 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"5º, LXXII, a","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false},{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-92","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":92,"source_origin":"CEBRASPE (CESPE) - TJ (STM)/STM/Apoio Especializado/Programação de Sistemas/2018","contest_year":2018,"question_text":"Julgue o item seguinte, relativo aos direitos e garantias fundamentais, ao meio ambiente e à organização político-administrativa. Constitui regra de garantia do direito humano fundamental ao meio ambiente a possibilidade de qualquer cidadão ser legitimado a propor ação popular visando à anulação de ato lesivo ao meio ambiente.","official_answer":"C","explanation":"A ação popular protege o ambiente. Origem declarada pela coletânea: CEBRASPE (CESPE) - TJ (STM)/STM/Apoio Especializado/Programação de Sistemas/2018. Item 92 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"5º, LXXIII","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false},{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-93","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":93,"source_origin":"CEBRASPE (CESPE) - AJ STJ/STJ/Judiciária/Oficial de Justiça Avaliador Federal/2018","contest_year":2018,"question_text":"Considerando a legislação, a doutrina e a jurisprudência dos tribunais superiores acerca dos direitos e das garantias fundamentais e da aplicabilidade das normas constitucionais, julgue o item a seguir. A isenção de custas processuais na ação popular para a defesa de interesse coletivo ou difuso inclui o ônus da sucumbência, salvo se comprovada má-fé.","official_answer":"C","explanation":"A má-fé afasta a isenção. Origem declarada pela coletânea: CEBRASPE (CESPE) - AJ STJ/STJ/Judiciária/Oficial de Justiça Avaliador Federal/2018. Item 93 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"5º, LXXIII","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false},{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-94","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":94,"source_origin":"CEBRASPE (CESPE) - Aux Inst (IPHAN)/IPHAN/Área 1/2018","contest_year":2018,"question_text":"A respeito dos direitos e das garantias fundamentais, julgue o item seguinte. Qualquer cidadão brasileiro em pleno exercício de seus direitos tem legitimidade para propor ação popular com intuito de anular ato lesivo ao patrimônio histórico e cultural.","official_answer":"C","explanation":"Cidadão pode proteger patrimônio cultural. Origem declarada pela coletânea: CEBRASPE (CESPE) - Aux Inst (IPHAN)/IPHAN/Área 1/2018. Item 94 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"5º, LXXIII","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false},{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-95","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":95,"source_origin":"CEBRASPE (CESPE) - AG (TCE-PE) /TCE\u0002PE/Julgamento/2017","contest_year":2017,"question_text":"Acerca dos princípios fundamentais e dos direitos e deveres individuais e coletivos, julgue o item a seguir. Se determinado dirigente de autarquia estadual editar ato administrativo lesivo ao patrimônio público, qualquer cidadão ou pessoa jurídica poderá propor ação popular para anular o referido ato, sem custas judiciais.","official_answer":"E","explanation":"Pessoa jurídica não é legitimada. Origem declarada pela coletânea: CEBRASPE (CESPE) - AG (TCE-PE) /TCE\u0002PE/Julgamento/2017. Item 95 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"5º, LXXIII","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false},{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-96","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":96,"source_origin":"CEBRASPE (CESPE) - AG (TCE-PE) /TCE\u0002PE/Julgamento/2017","contest_year":2017,"question_text":"Com relação aos direitos sociais, aos direitos de nacionalidade, aos direitos políticos e aos partidos políticos, julgue o item. O transporte e o lazer são direitos sociais expressamente previstos na CF.","official_answer":"C","explanation":"Transporte e lazer são direitos sociais. Origem declarada pela coletânea: CEBRASPE (CESPE) - AG (TCE-PE) /TCE\u0002PE/Julgamento/2017. Item 96 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"6º","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false},{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-102","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":102,"source_origin":"CEBRASPE (CESPE) - Aux Inst (IPHAN)/IPHAN/Área 1/2018","contest_year":2018,"question_text":"A respeito dos direitos e das garantias fundamentais, julgue o item seguinte. Situação hipotética: João, cuja mãe é brasileira e cujo pai é espanhol e mora em Londres, nasceu em país estrangeiro e não foi registrado em repartição brasileira competente. Hoje, aos 21 anos de idade, ele reside no Brasil e pretende requerer a nacionalidade brasileira. Assertiva: Nesse caso, poderá ser conferida a João a condição de brasileiro nato.","official_answer":"C","explanation":"Residência e opção permitem nacionalidade originária. Origem declarada pela coletânea: CEBRASPE (CESPE) - Aux Inst (IPHAN)/IPHAN/Área 1/2018. Item 102 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"12, I, c","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false},{"external_item_key":"drive-1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn-104","source_id":"1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn","source_item_number":104,"source_origin":"CEBRASPE (CESPE) - AG (TCE-PE) /TCE\u0002PE/Administração/2017","contest_year":2017,"question_text":"Considerando o que dispõe a CF acerca dos direitos sociais, direitos de nacionalidade e direitos políticos, bem como dos partidos políticos, julgue o item subsequente. Situação hipotética: Cláudio, brasileiro nato, por interesse exclusivamente pessoal, residiu em país estrangeiro, onde teve um filho com uma cidadã local. Assertiva: Nessa situação, segundo a CF, o filho de Cláudio poderá ser considerado brasileiro nato, ainda que não venha a residir no Brasil.","official_answer":"C","explanation":"O registro consular dispensa residência no Brasil. Origem declarada pela coletânea: CEBRASPE (CESPE) - AG (TCE-PE) /TCE\u0002PE/Administração/2017. Item 104 do PDF. Conferência textual em 30/09/2026; aguarda conferência visual e de contexto antes da publicação.","legal_basis":[{"norma":"Constituição Federal","artigo":"12, I, c","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm"}],"content_status":"under_review","is_original":false}]'::jsonb) as x(external_item_key text,contest_year int,question_text text,official_answer text,explanation text,legal_basis jsonb)), inserted as (
insert into public.curated_question_catalog(source_id,syllabus_topic_id,external_item_key,contest_name,contest_year,career_name,exam_board,subject,subtopic,question_text,official_answer,explanation,legal_basis,difficulty,content_status,is_original,law_version_checked_at)
select s.id,t.id,i.external_item_key,'Repertório CEBRASPE — Direito Constitucional',i.contest_year,'Agente de Polícia Federal','CEBRASPE','Direito Constitucional','Direitos fundamentais, sociais e nacionalidade',i.question_text,i.official_answer,i.explanation,i.legal_basis,'média','under_review',false,'2026-09-30T00:00:00-03:00'::timestamptz
from incoming i cross join public.content_sources s cross join public.syllabus_topics t join public.syllabus_editions e on e.id=t.edition_id
where s.url='https://drive.google.com/file/d/1PKj-SV8e-8bWKTNhIj5LVBIZJaMRHqSn/view' and e.contest_name='Polícia Federal' and e.role_name='Agente de Polícia Federal' and e.contest_year=2025 and e.status='active' and t.discipline='Noções de Direito Constitucional' and t.topic_order=1 and t.content_status='current' and t.block_name not ilike '%Hist%'
and not exists(select 1 from public.curated_question_catalog c where regexp_replace(lower(c.question_text),'[[:space:]]+',' ','g')=regexp_replace(lower(i.question_text),'[[:space:]]+',' ','g'))
and not exists(select 1 from public.official_exam_questions c where regexp_replace(lower(c.question_text),'[[:space:]]+',' ','g')=regexp_replace(lower(i.question_text),'[[:space:]]+',' ','g'))
and not exists(select 1 from public.question_bank c where regexp_replace(lower(c.question_text),'[[:space:]]+',' ','g')=regexp_replace(lower(i.question_text),'[[:space:]]+',' ','g'))
on conflict(source_id,external_item_key) do nothing returning external_item_key)
